{"files":[{"path":"src/occupationalInfo/date.mjs","content":"export function validateSurveyDate(value, today) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return '日期格式错误';
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return '日期无效';
  }
  if (value > today) return '调查日期不能晚于今日';
  return '';
}
"},{"path":"src/occupationalInfo/form.mjs","content":"import { validateSurveyDate } from './date.mjs';
export function submitSurvey(form, today) {
  const error = validateSurveyDate(form.surveyDate, today);
  if (error) return { ok: false, error };
  return { ok: true, value: { ...form } };
}
"},{"path":"src/occupationalInfo/import.mjs","content":"import { validateSurveyDate } from './date.mjs';
export function importSurveys(rows, today) {
  const accepted = [], errors = [];
  rows.forEach((row, index) => {
    const error = validateSurveyDate(row.surveyDate, today);
    if (error) errors.push({ row: index + 1, message: error });
    else accepted.push({ ...row });
  });
  return { accepted, errors };
}
